package com.yuegang.zhihui.product.security;import com.yuegang.zhihui.common.core.*;import com.yuegang.zhihui.common.security.*;import jakarta.servlet.http.*;import java.time.*;import java.util.*;public final class ProductAdminVerifier{private final InternalUserContextSignature s;public ProductAdminVerifier(byte[]k){s=new InternalUserContextSignature(k,Clock.systemUTC(),Duration.ofSeconds(30));}public void verify(HttpServletRequest r){try{String u=h(r,"X-YGH-User-Id");var roles=v(r.getHeader("X-YGH-Roles"));var perms=v(r.getHeader("X-YGH-Permissions"));var m=new InternalUserContextSignature.Metadata(u,roles,perms,h(r,"X-Trace-Id"),h(r,"X-Request-Id"),r.getMethod(),r.getRequestURI(),Instant.ofEpochMilli(Long.parseLong(h(r,"X-YGH-User-Context-Timestamp"))));if(!s.verify(m,h(r,"X-YGH-User-Context-Signature"))||!roles.contains("ADMIN"))throw f();}catch(Exception e){throw f();}}private static String h(HttpServletRequest r,String n){String v=r.getHeader(n);if(v==null||v.isBlank())throw f();return v;}private static List<String>v(String x){return x==null||x.isBlank()?List.of():List.of(x.split(","));}private static BusinessException f(){return new BusinessException(ErrorCode.PERMISSION_DENIED);}}
